) as (
  values
    ('元首', '各国元首在峰会上表达了共同的合作意愿。', 'nguyên thủ', 'yuán shǒu', '各国元首在峰会上表达了共同的合作意愿。', 'nguyên thủ', 'yuán shǒu', 'Gèguó yuánshǒu zài fēnghuì shàng biǎodále gòngtóng de hézuò yìyuàn.', 'Nguyên thủ các nước đã bày tỏ nguyện vọng hợp tác chung tại hội nghị thượng đỉnh.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-20d80a9eb3997e40a9e2c459.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-f35c89381d5cc900ba25f75e.mp3'),
    ('元素', '水是生命不可缺少的基本元素之一。', 'nguyên tố', 'yuán sù', '水是生命不可缺少的基本元素之一。', 'nguyên tố', 'yuán sù', 'Shuǐ shì shēngmìng bùkě quēshǎo de jīběn yuánsù zhī yī.', 'Nước là một trong những nguyên tố cơ bản không thể thiếu của sự sống.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-a1c1675f5df836a886300406.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-4de052fc64f6832726ddfba5.mp3'),
    ('元宵节', '我们一家人在元宵节那天一起吃汤圆庆祝。', 'tết Nguyên tiêu', 'yuán xiāo jié', '我们一家人在元宵节那天一起吃汤圆庆祝。', 'tết Nguyên tiêu', 'yuán xiāo jié', 'Wǒmen yījiā rén zài Yuánxiāo Jié nà tiān yīqǐ chī tāngyuán qìngzhù.', 'Gia đình chúng tôi cùng ăn bánh trôi trong ngày Tết Nguyên tiêu để mừng.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-ef91ce2a8b18e87b0a426311.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-1ae3cfce7ab589c7998d5fc8.mp3'),
    ('依靠', '年轻人在成长过程中需要依靠家人的支持和关爱。', 'chỗ dựa', 'yī kào', '年轻人在成长过程中需要依靠家人的支持和关爱。', 'chỗ dựa', 'yī kào', 'Niánqīng rén zài chéngzhǎng guòchéng zhōng xūyào yīkào jiārén de zhīchí hé guān''ài.', 'Người trẻ trong quá trình trưởng thành cần có chỗ dựa là sự ủng hộ và quan tâm của gia đình.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-81766ce3e3b666baab847b25.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-efbe2beea4d8bfd431b163d4.mp3'),
    ('依赖', '孩子们不应该过度依赖电子产品，要学会独立思考。', 'dựa dẫm', 'yī lài', '孩子们不应该过度依赖电子产品，要学会独立思考。', 'dựa dẫm', 'yī lài', 'Háizimen bù yīnggāi guòdù yīlài diànzǐ chǎnpǐn, yào xuéhuì dúlì sīkǎo.', 'Trẻ em không nên quá dựa dẫm vào thiết bị điện tử, phải học cách suy nghĩ độc lập.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-7767404865402072987eb6d6.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-84b7b814387171cc77583cec.mp3'),
    ('依旧', '虽然时间过去多年，他的笑容依旧那么温暖。', 'như xưa', 'yī jiù', '虽然时间过去多年，他的笑容依旧那么温暖。', 'như xưa', 'yī jiù', 'Suīrán shíjiān guòqù duōnián, tā de xiàoróng yījiù nàme wēnnuǎn.', 'Dù đã nhiều năm trôi qua, nụ cười của anh ấy vẫn ấm áp như xưa.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-cf4e237f77b8f1eda6405c9a.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-c6b66914219ebe1bfde54e77.mp3'),
    ('依据', '法院的判决必须严格依据法律条款。', 'căn cứ', 'yī jù', '法院的判决必须严格依据法律条款。', 'căn cứ', 'yī jù', 'Fǎyuàn de pànjué bìxū yángé yījù fǎlǜ tiáokuǎn.', 'Phán quyết của tòa án phải dựa trên các điều khoản pháp luật một cách nghiêm ngặt.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-2e9f011743981bcd1fda076f.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-a5ca911303d493918f1e1ebb.mp3'),
    ('依托', '这家公司依托先进的技术迅速发展起来。', 'dựa vào, nhờ', 'yī tuō', '这家公司依托先进的技术迅速发展起来。', 'dựa vào, nhờ', 'yī tuō', 'Zhè jiā gōngsī yītuō xiānjìn de jìshù xùnsù fāzhǎn qǐlái.', 'Công ty này dựa vào công nghệ tiên tiến để phát triển nhanh chóng.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-f0a96159e5264c33c3659981.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-72e8d616776c82c0eda43f2f.mp3'),
    ('优越', '他凭借优越的条件获得了这次比赛的冠军。', 'ưu việt', 'yōu yuè', '他凭借优越的条件获得了这次比赛的冠军。', 'ưu việt', 'yōu yuè', 'Tā píngjiè yōuyuè de tiáojiàn huòdéle zhè cì bǐsài de guànjūn.', 'Anh ấy nhờ điều kiện ưu việt đã giành được chức vô địch trong cuộc thi này.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-5e49c3015b91a6ddfe49a3a6.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-fe27ad197b886802778be00d.mp3'),
    ('优胜劣汰', '在激烈的市场竞争中，优胜劣汰是常态。', 'mạnh được yếu thua', 'yōu shèng liè tài', '在激烈的市场竞争中，优胜劣汰是常态。', 'mạnh được yếu thua', 'yōu shèng liè tài', 'Zài jīliè de shìchǎng jìngzhēng zhōng, yōushèng liètāi shì chángtài.', 'Trong cạnh tranh thị trường khốc liệt, mạnh được yếu thua là điều bình thường.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-b9b688176b70b183bd218dbd.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-bba02f84d61b64156c99b9b0.mp3'),
    ('优异', '他在学术研究方面取得了优异的成绩。', 'xuất sắc', 'yōu yì', '他在学术研究方面取得了优异的成绩。', 'xuất sắc', 'yōu yì', 'Tā zài xuéshù yánjiū fāngmiàn qǔdéle yōuyì de chéngjī.', 'Anh ấy đã đạt được thành tích xuất sắc trong lĩnh vực nghiên cứu học thuật.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-38c948c6212fdb32df9b733b.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-b9b1378a9521270b2feddd3d.mp3'),
    ('优先', '紧急情况下，伤者必须被优先救治。', 'ưu tiên', 'yōu xiān', '紧急情况下，伤者必须被优先救治。', 'ưu tiên', 'yōu xiān', 'Jǐnjí qíngkuàng xià, shāngzhě bìxū bèi yōuxiān jiùzhì.', 'Trong tình huống khẩn cấp, những người bị thương phải được cứu chữa ưu tiên.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-1a93c20d40a9b7cb94337911.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-8c566109f9d1f3761b0a52c4.mp3'),
    ('仪式', '毕业典礼的仪式非常庄重隆重，令人难忘。', 'nghi thức', 'yí shì', '毕业典礼的仪式非常庄重隆重，令人难忘。', 'nghi thức', 'yí shì', 'Bìyè diǎnlǐ de yíshì fēicháng zhuāngzhòng lóngzhòng, lìng rén nánwàng.', 'Nghi thức lễ tốt nghiệp rất trang trọng và long trọng, gây ấn tượng khó quên.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-d41be15e315b2f19e5eca002.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-fe2bb1f2eb2ac9ba618ec086.mp3'),
    ('仪器', '科学家使用精密仪器进行实验数据的测量。', 'máy đo', 'yí qì', '科学家使用精密仪器进行实验数据的测量。', 'máy đo', 'yí qì', 'Kēxuéjiā shǐyòng jīngmì yíqì jìnxíng shíyàn shùjù de cèliáng.', 'Các nhà khoa học sử dụng thiết bị máy đo tinh vi để đo dữ liệu thí nghiệm.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-44b2c9991ba1303e58e805bd.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-2aaeb69475e0bb05b65f9a2b.mp3'),
    ('以致', '他的错误决定以致公司遭受了严重损失。', 'dẫn đến', 'yǐ zhì', '他的错误决定以致公司遭受了严重损失。', 'dẫn đến', 'yǐ zhì', 'Tā de cuòwù juédìng yǐzhì gōngsī zāoshòule yánzhòng sǔnshī.', 'Quyết định sai lầm của anh ta dẫn đến công ty chịu tổn thất nghiêm trọng.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-aef1fb0ce204d6c55ae4a82a.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-ed2443559945c360a8e091e0.mp3'),
    ('以至', '天气持续寒冷，以至于很多居民都感冒了。', 'thế nên', 'yǐ zhì', '天气持续寒冷，以至于很多居民都感冒了。', 'thế nên', 'yǐ zhì', 'Tiānqì chíxù hánlěng, yǐzhì yú hěn duō jūmín dōu gǎnmào le.', 'Thời tiết liên tục lạnh đến mức nhiều cư dân đều bị cảm.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-c79e23dbe713651dc48a27e6.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-15501c27f3b63e344b9057fe.mp3'),
    ('以往', '以往这里是一个热闹的市场，现在已经变得安静了。', 'trước kia', 'yǐ wǎng', '以往这里是一个热闹的市场，现在已经变得安静了。', 'trước kia', 'yǐ wǎng', 'Yǐwǎng zhèlǐ shì yīgè rènào de shìchǎng, xiànzài yǐjīng biàndé ānjìng le.', 'Trước kia nơi đây là một khu chợ nhộn nhịp, bây giờ đã trở nên yên tĩnh.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-8339e57693578b2bb585832e.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-7e57bb97a84db610c9a42aca.mp3'),
    ('以免', '请提前通知对方，以免发生误会。', 'để tránh', 'yǐ miǎn', '请提前通知对方，以免发生误会。', 'để tránh', 'yǐ miǎn', 'Qǐng tíqián tōngzhī duìfāng, yǐmiǎn fāshēng wùhuì.', 'Xin hãy thông báo trước cho đối phương để tránh xảy ra hiểu lầm.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-798e8db910280b6b80f45be0.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-e4057e4ce5a81f7f01fe0e92.mp3'),
    ('以便', '我提前准备资料，以便开会时使用。', 'để tiện', 'yǐ biàn', '我提前准备资料，以便开会时使用。', 'để tiện', 'yǐ biàn', 'Wǒ tíqián zhǔnbèi zīliào, yǐbiàn kāihuì shí shǐyòng.', 'Tôi chuẩn bị tài liệu trước để tiện sử dụng trong buổi họp.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-5abcf76d8907a672276bacb1.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-384ec70d49b1d8eac5d95369.mp3'),
    ('亦', '他不仅是一名优秀的老师，亦是一位出色的作家。', 'cũng', 'yì', '他不仅是一名优秀的老师，亦是一位出色的作家。', 'cũng', 'yì', 'Tā bùjǐn shì yī míng yōuxiù de lǎoshī, yì shì yī wèi chūsè de zuòjiā.', 'Anh ấy không chỉ là một giáo viên xuất sắc mà còn là một nhà văn tài năng.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-2c11629102a454f069679fdd.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-f7e1aa1697e343787a3af979.mp3'),
    ('亚军', '这次比赛他获得了亚军，表现非常出色。', 'á quân', 'yà jūn', '这次比赛他获得了亚军，表现非常出色。', 'á quân', 'yà jūn', 'Zhè cì bǐ sài tā huò dé le yà jūn, biǎo xiàn fēi cháng chū sè.', 'Trong cuộc thi này, anh ấy đã giành á quân, thể hiện rất xuất sắc.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-43eb2685a3451855bfbd3d76.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-fd34ea281a8c80df23232d33.mp3'),
    ('乐谱', '钢琴老师给我发了一份新的乐谱，让我练习。', 'bản nhạc', 'yuè pǔ', '钢琴老师给我发了一份新的乐谱，让我练习。', 'bản nhạc', 'yuè pǔ', 'Gāng qín lǎo shī gěi wǒ fā le yī fèn xīn de yuè pǔ, ràng wǒ liàn xí.', 'Thầy dạy đàn piano đã gửi cho tôi một bản nhạc mới để luyện tập.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-2f2b7b30adf3e5a2192d7e91.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-b7b638ffe1b28d2b58b7c5c1.mp3'),
    ('严禁', '这里严禁吸烟，违者将被罚款。', 'nghiêm cấm', 'yán jìn', '这里严禁吸烟，违者将被罚款。', 'nghiêm cấm', 'yán jìn', 'Zhè lǐ yán jìn xī yān, wéi zhě jiāng bèi fá kuǎn.', 'Ở đây nghiêm cấm hút thuốc, vi phạm sẽ bị phạt tiền.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-0b6e464968bcef0a7363e593.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-d47939f2f22eb5aa770f5dfc.mp3'),
    ('严峻', '面对严峻的考验，我们必须坚持不懈。', 'cam go, khắt khe', 'yán jùn', '面对严峻的考验，我们必须坚持不懈。', 'cam go, khắt khe', 'yán jùn', 'Miàn duì yán jùn de kǎo yàn, wǒ men bì xū jiān chí bù xiè.', 'Đối mặt với những thử thách cam go, chúng ta phải kiên trì không ngừng.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-35f05b2b2574ab51c43f911a.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-dc363221fffde739d8be9add.mp3'),
    ('严寒', '北方的严寒使得农作物难以生长。', 'lạnh', 'yán hán', '北方的严寒使得农作物难以生长。', 'lạnh', 'yán hán', 'Běi fāng de yán hán shǐ dé nóng zuò wù nán yǐ shēng zhǎng.', 'Thời tiết lạnh khắc nghiệt ở miền Bắc khiến cây trồng khó phát triển.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-53647796c4ae9cf42825265b.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-120b00c66f83487d1d1100c5.mp3'),
    ('严密', '警方对案发现场进行了严密的调查。', 'nghiêm ngặt', 'yán mì', '警方对案发现场进行了严密的调查。', 'nghiêm ngặt', 'yán mì', 'Jǐng fāng duì àn fā xiàn chǎng jìn xíng le yán mì de diào chá.', 'Cảnh sát đã tiến hành điều tra nghiêm ngặt hiện trường vụ án.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-df44b10051e2a43392f1aee9.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-2cf248c958dfbace68ef26ae.mp3'),
    ('严厉', '老师对学生的纪律要求非常严厉。', 'nghiêm khắc', 'yán lì', '老师对学生的纪律要求非常严厉。', 'nghiêm khắc', 'yán lì', 'Lǎo shī duì xué shēng de jì lǜ yāo qiú fēi cháng yán lì.', 'Giáo viên yêu cầu kỷ luật với học sinh rất nghiêm khắc.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-3658431b436a961fe481a44f.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-f086c91fd1be54af3a0bf4d9.mp3'),
    ('与日俱增', '他的工作压力与日俱增，需要及时调整心态。', 'tăng lên từng ngày', 'yǔ rì jù zēng', '他的工作压力与日俱增，需要及时调整心态。', 'tăng lên từng ngày', 'yǔ rì jù zēng', 'Tā de gōng zuò yā lì yǔ rì jù zēng, xū yào jí shí tiáo zhěng xīn tài.', 'Áp lực công việc của anh ấy tăng lên từng ngày, cần phải điều chỉnh tâm trạng kịp thời.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-0f95d05e055e34f4053cd2cd.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-978c98e004588a80189efc62.mp3'),
    ('一贯', '他一贯保持乐观的态度，很少抱怨。', 'nhaất quán', 'yī guàn', '他一贯保持乐观的态度，很少抱怨。', 'nhaất quán', 'yī guàn', 'Tā yī guàn bǎo chí lè guān de tài dù, hěn shǎo bào yuàn.', 'Anh ấy luôn giữ thái độ lạc quan và rất ít phàn nàn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-23b8af7a9c96fff9b5cb3a8c.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-81bd7d057ab483ddf593ec08.mp3'),
    ('一目了然', '这张地图结构清晰，一目了然。', 'rõ ràng, dễ nhìn', 'yī mù liǎo rán', '这张地图结构清晰，一目了然。', 'rõ ràng, dễ nhìn', 'yī mù liǎo rán', 'Zhè zhāng dì tú jié gòu qīng xī, yī mù liǎo rán.', 'Bản đồ này có cấu trúc rõ ràng, nhìn là hiểu.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-581e9713dece4bfbca17b723.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-cdb228cf56e92f9d87211f4b.mp3'),
    ('一流', '她是一流的医生，技术非常高超。', 'hạng nhất', 'yī liú', '她是一流的医生，技术非常高超。', 'hạng nhất', 'yī liú', 'Tā shì yī liú de yī shēng, jì shù fēi cháng gāo chāo.', 'Cô ấy là bác sĩ hàng đầu, kỹ thuật rất xuất sắc.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-4f9499b7cd6e8f0d0d9974e5.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-e012de29abdfaef57e2d20e8.mp3'),
    ('一度', '这部电影一度成为票房冠军，受到了广泛好评。', 'một lần', 'yī dù', '这部电影一度成为票房冠军，受到了广泛好评。', 'một lần', 'yī dù', 'Zhè bù diàn yǐng yī dù chéng wéi piào fáng guàn jūn, shòu dào le guǎng fàn hǎo píng.', 'Bộ phim này từng một lần trở thành quán quân phòng vé và nhận được nhiều đánh giá tốt.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-e4eec3025cd7c347deef7c73.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-a02f20ccd8be6f99b6c53bfe.mp3'),
    ('一帆风顺', '祝你未来的事业一帆风顺，取得更大成就。', 'thuận buồm xuôi gió', 'yī fān fēng shùn', '祝你未来的事业一帆风顺，取得更大成就。', 'thuận buồm xuôi gió', 'yī fān fēng shùn', 'Zhù nǐ wèi lái de shì yè yī fān fēng shùn, qǔ dé gèng dà chéng jiù.', 'Chúc bạn sự nghiệp tương lai thuận buồm xuôi gió, đạt được thành tựu lớn hơn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-7ee0421dd8b8ff7b74e2a222.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-40d623f385c1675134edadad.mp3'),
    ('一如既往', '他对工作的态度一如既往地认真负责。', 'vẫn như xưa', 'yī rú jì wǎng', '他对工作的态度一如既往地认真负责。', 'vẫn như xưa', 'yī rú jì wǎng', 'Tā duì gōng zuò de tài dù yī rú jì wǎng de rèn zhēn fù zé.', 'Anh ấy luôn nghiêm túc và có trách nhiệm với công việc như trước giờ.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-cdf8e8de3967b4e96a121b21.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-49d2fca42487de21ed6c3292.mp3'),
    ('一向', '他一向喜欢早起锻炼身体，从不懈怠。', 'luôn luôn', 'yī xiàng', '他一向喜欢早起锻炼身体，从不懈怠。', 'luôn luôn', 'yī xiàng', 'Tā yī xiàng xǐ huān zǎo qǐ duàn liàn shēn tǐ, cóng bù xiè dài.', 'Anh ấy luôn thích dậy sớm tập thể dục và chưa bao giờ lười biếng.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-782b06f181a3a9c899a301e7.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-8f075e04509dee2fe392a1d0.mp3'),
    ('一举两得', '参加这个培训既能提升技能，又能认识新朋友，真是一举两得。', 'nhất cử lưỡng tiện', 'yī jǔ liǎng dé', '参加这个培训既能提升技能，又能认识新朋友，真是一举两得。', 'nhất cử lưỡng tiện', 'yī jǔ liǎng dé', 'Cān jiā zhè ge péi xùn jì néng tí shēng jì néng, yòu néng rèn shi xīn péng yǒu, zhēn shì yī jǔ liǎng dé.', 'Tham gia khóa đào tạo này vừa nâng cao kỹ năng lại vừa kết bạn mới thật là nhất cử lưỡng tiện.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-c289846e70854b67c29da367.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-0d37e77a0a4f5e56606ceaed.mp3'),
    ('一丝不苟', '他做事一丝不苟，从不马虎。', 'không hề cẩu thả', 'yī sī bù gǒu', '他做事一丝不苟，从不马虎。', 'không hề cẩu thả', 'yī sī bù gǒu', 'Tā zuò shì yī sī bù gǒu, cóng bù mǎ hǔ.', 'Anh ấy làm việc rất cẩn thận, chưa bao giờ qua loa.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-84598e61cfc4848ede186989.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-3d2e49158a3a6314ba07ba67.mp3'),
    ('熨', '妈妈教我怎么用熨斗熨平衣服上的皱纹。', 'bàn là', 'yùn', '妈妈教我怎么用熨斗熨平衣服上的皱纹。', 'bàn là', 'yùn', 'Mā mā jiāo wǒ zěn me yòng yùn dǒu yùn píng yī fu shàng de zhòu wén.', 'Mẹ dạy tôi cách dùng bàn là để là phẳng các nếp nhăn trên quần áo.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-7f2ecefefc5695e0e6e7eb5a.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-0772525ad95f4504a1bb34b9.mp3'),
    ('驻扎', '军队在边境地区驻扎，以确保安全。', 'đóng quân', 'zhù zhā', '军队在边境地区驻扎，以确保安全。', 'đóng quân', 'zhù zhā', 'Jūn duì zài biān jìng dì qū zhù zhā, yǐ què bǎo ān quán.', 'Quân đội đóng quân ở khu vực biên giới để đảm bảo an ninh.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-f6368b6045573ad9514ac90d.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-5ac01967c34781013d6dc994.mp3'),
    ('震撼', '这部电影的剧情非常震撼，让人难以忘怀。', 'bị sốc, chấn động', 'zhèn hàn', '这部电影的剧情非常震撼，让人难以忘怀。', 'bị sốc, chấn động', 'zhèn hàn', 'Zhè bù diàn yǐng de jù qíng fēi cháng zhèn hàn, ràng rén nán yǐ wàng huái.', 'Cốt truyện của bộ phim này rất gây ấn tượng mạnh, khiến người ta khó quên.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-512d4a2e968903833220b434.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-370f97e4af8f9ac9bb624e98.mp3'),
    ('震惊', '这则新闻的内容让整个社会感到震惊。', 'chấn động (dư luận, thế giới)', 'zhèn jīng', '这则新闻的内容让整个社会感到震惊。', 'chấn động (dư luận, thế giới)', 'zhèn jīng', 'Zhè zé xīnwén de nèiróng ràng zhěnggè shèhuì gǎndào zhènjīng.', 'Nội dung tin tức này khiến cả xã hội cảm thấy chấn động.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-341533806f14a44f1dae8d2b.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-2b2be70ad1ec0a4a32aeef40.mp3'),
    ('障碍', '语言障碍是我们交流时遇到的主要问题。', 'trở ngại', 'zhàng ài', '语言障碍是我们交流时遇到的主要问题。', 'trở ngại', 'zhàng ài', 'Yǔyán zhàng''ài shì wǒmen jiāoliú shí yù dào de zhǔyào wèntí.', 'Trở ngại ngôn ngữ là vấn đề chính khi chúng ta giao tiếp.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-4fcac52025755f8b70f36a30.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-1f4a939870f5eafb61671b7b.mp3'),
    ('阻碍', '缺乏资金严重阻碍了项目的顺利进行。', 'cản trở', 'zǔ ài', '缺乏资金严重阻碍了项目的顺利进行。', 'cản trở', 'zǔ ài', 'Quēfá zījīn yánzhòng zǔ''ài le xiàngmù de shùnlì jìnxíng.', 'Thiếu vốn nghiêm trọng cản trở tiến độ suôn sẻ của dự án.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-5a61a426999aafa1bd7afc4c.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-7246b63230625cbebf714f79.mp3'),
    ('阻挠', '敌人的策略不断阻挠我们的计划实施。', 'cản trở, ngăn chặn', 'zǔ náo', '敌人的策略不断阻挠我们的计划实施。', 'cản trở, ngăn chặn', 'zǔ náo', 'Dírén de cèlüè bùduàn zǔnáo wǒmen de jìhuà shíshī.', 'Chiến lược của địch liên tục ngăn chặn việc thực hiện kế hoạch của chúng ta.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-a78b0af5f5b0bf366ddc58b2.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-486342730a66f1af55f6d81b.mp3'),
    ('阻拦', '警察成功阻拦了那些试图逃跑的罪犯。', 'ngăn cản', 'zǔ lán', '警察成功阻拦了那些试图逃跑的罪犯。', 'ngăn cản', 'zǔ lán', 'Jǐngchá chénggōng zǔlán le nàxiē shìtú táopǎo de zuìfàn.', 'Cảnh sát đã thành công ngăn cản những tội phạm cố gắng bỏ chạy.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-2251a494ab48816e752a8b63.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-e0cf35637731a262a5f7a1df.mp3'),
    ('阵容', '这次比赛的队伍阵容比以往更加强大。', 'đội hình', 'zhèn róng', '这次比赛的队伍阵容比以往更加强大。', 'đội hình', 'zhèn róng', 'Zhè cì bǐsài de duìwǔ zhènróng bǐ yǐwǎng gèng jiā qiángdà.', 'Đội hình của đội trong trận đấu lần này mạnh hơn mọi khi.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-5e688f58feba56891e64f5dd.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-a01a54c3b3c9f62056a01913.mp3'),
    ('阵地', '士兵们坚守在前线阵地上抵御敌人进攻。', 'trận địa', 'zhèn dì', '士兵们坚守在前线阵地上抵御敌人进攻。', 'trận địa', 'zhèn dì', 'Shìbīngmen jiānshǒu zài qiánxiàn zhèndì shàng dǐyù dírén jìngōng.', 'Binh lính kiên cường giữ vững trận địa tiền tuyến để chống lại địch.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-7e82a3544e3570106cf985a0.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-763c81f513bb42a9b3ed8d55.mp3'),
    ('镇静', '面对突发状况，他始终保持镇静和冷静。', 'bình tĩnh', 'zhèn jìng', '面对突发状况，他始终保持镇静和冷静。', 'bình tĩnh', 'zhèn jìng', 'Miànduì túfā zhuàngkuàng, tā shǐzhōng bǎochí zhènjìng hé lěngjìng.', 'Đối mặt với tình huống bất ngờ, anh ấy luôn giữ bình tĩnh và điềm đạm.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-aa3880110720f9c93a19bfeb.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-83768888a913c5f63ebd7ff5.mp3'),
    ('镇定', '她镇定地处理了紧急事件，避免了更大损失。', 'chấn tĩnh', 'zhèn dìng', '她镇定地处理了紧急事件，避免了更大损失。', 'chấn tĩnh', 'zhèn dìng', 'Tā zhèndìng de chǔlǐ le jǐnjí shìjiàn, bìmiǎn le gèng dà sǔnshī.', 'Cô ấy xử lý sự cố khẩn cấp một cách chấn tĩnh, tránh được thiệt hại lớn hơn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-3845b6f882b0e8d3be618fc2.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-bd272ed5477ec4c19582da82.mp3'),
    ('铸造', '这家工厂专门铸造高质量的金属零件。', 'đúc', 'zhù zào', '这家工厂专门铸造高质量的金属零件。', 'đúc', 'zhù zào', 'Zhè jiā gōngchǎng zhuānmén zhùzào gāo zhìliàng de jīnshǔ língjiàn.', 'Nhà máy này chuyên đúc các bộ phận kim loại chất lượng cao.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-8cf2eb81849ec25103a1d9a7.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-9671e5f682e3290c20acb5e8.mp3'),
    ('钻研', '他花了多年时间深入钻研人工智能技术。', 'nghiên cứu chuyên sâu', 'zuān yán', '他花了多年时间深入钻研人工智能技术。', 'nghiên cứu chuyên sâu', 'zuān yán', 'Tā huā le duō nián shíjiān shēnrù zuānyán réngōng zhìnéng jìshù.', 'Anh ấy đã dành nhiều năm nghiên cứu chuyên sâu về công nghệ trí tuệ nhân tạo.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-525ff1fbe18aaf177c989c8e.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-aabf3bedd51f6c960637ce52.mp3'),
